DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['levelup_roles','exams','exam_sections','domains','topics','subtopics','content_sources','questions','question_versions','question_options','question_explanations','media_assets','question_media','learning_modules','learning_lessons','lesson_blocks','lesson_question_assignments','content_reviews','import_jobs','import_rows'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated',t);EXECUTE format('GRANT ALL ON public.%I TO service_role',t);END LOOP;END $$;
REVOKE ALL ON public.levelup_question_bank FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.levelup_question_bank TO service_role;
REVOKE ALL ON FUNCTION public.levelup_question_ready(uuid),public.levelup_content_immutable(),public.levelup_publish_guard(),public.levelup_option_guard(),public.levelup_question_delete_guard() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.levelup_question_ready(uuid) TO service_role;
COMMIT;
